function fragments(payload, mtu) {
  // TODO:
  // - each fragment holds at most (mtu - 20) payload bytes (20-byte IPv4 header)
  // - the fragment offset counts 8-byte units, so round that max DOWN to a
  //   multiple of 8 before dividing
  // - return the number of fragments needed for `payload` bytes
  return 0;
}

// 4000 bytes of payload over a 1500-byte MTU.
// max data per fragment = floor((1500-20)/8)*8 = 1480 -> ceil(4000/1480) = 3
if (fragments(4000, 1500) !== 3) throw new Error('expected 3 fragments, got ' + fragments(4000, 1500));
// 4000 over a 1400-byte path: max data = floor(1380/8)*8 = 1376 -> ceil(4000/1376) = 3
if (fragments(4000, 1400) !== 3) throw new Error('expected 3, got ' + fragments(4000, 1400));
// exactly one fragment when it already fits
if (fragments(1000, 1500) !== 1) throw new Error('expected 1, got ' + fragments(1000, 1500));
console.log('OK');
